-- DeepEval — Тестування, Моніторинг і оцінка LLM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/confident-ai/deepeval' OR LOWER(`name`) = 'deepeval')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'DeepEval', NULL, 'https://github.com/confident-ai/deepeval', NULL, NULL, 'Відкритий фреймворк для тестування LLM-застосунків у стилі pytest: десятки готових метрик для RAG, агентів і чат-ботів.', 'Open-source pytest-style framework for testing LLM apps: dozens of ready metrics for RAG, agents and chatbots.', 'DeepEval дозволяє писати тести для LLM-застосунку як звичайні юніт-тести на Python і запускати їх командою deepeval test run або в CI. Є готові метрики для RAG (релевантність відповіді, faithfulness, contextual precision і recall), для агентів (виконання задачі, правильність інструментів і аргументів, дотримання плану), для багатокрокових діалогів, а також G-Eval для власних критеріїв, перевірки галюцинацій, упередженості, токсичності й коректності JSON. Інтегрується з LangChain, OpenAI, CrewAI. Ліцензія Apache 2.0; результати можна надсилати в комерційну платформу Confident AI.', 'DeepEval lets you write tests for an LLM app like ordinary Python unit tests and run them with deepeval test run or in CI. It ships metrics for RAG (answer relevancy, faithfulness, contextual precision and recall), agents (task completion, tool and argument correctness, plan adherence), multi-turn conversations, plus G-Eval for custom criteria and checks for hallucination, bias, toxicity and JSON correctness. Integrates with LangChain, OpenAI and CrewAI. Apache 2.0 license; results can be sent to the commercial Confident AI platform.', 'Тести LLM у стилі pytest
Метрики RAG, агентів і діалогів
G-Eval для власних критеріїв
Запуск у CI', 'pytest-style LLM tests
RAG, agent and conversation metrics
G-Eval for custom criteria
Runs in CI', 'QA-інженери, розробники й ML-інженери, що перевіряють якість відповідей чат-ботів, RAG-систем і АІ-агентів', 'QA engineers, developers and ML engineers checking the answer quality of chatbots, RAG systems and AI agents', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
