-- Ragas — Тестування, Моніторинг і оцінка LLM
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'docs.ragas.io' OR LOWER(`name`) = 'ragas')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Ragas', NULL, 'https://docs.ragas.io', NULL, NULL, 'Відкрита бібліотека для оцінювання RAG-систем і LLM-застосунків: метрики пошуку й відповіді, генерація тестових наборів.', 'Open-source library for evaluating RAG systems and LLM apps: retrieval and answer metrics, test set generation.', 'Ragas — один із найвідоміших інструментів для оцінювання RAG. Метрики Context Precision і Context Recall показують, чи знайшов пошук потрібні фрагменти, Faithfulness — чи відповідь спирається на знайдене без вигадок, Response Relevancy — чи відповідь стосується питання; є також Noise Sensitivity, метрики для агентів і виклику інструментів (Tool Call Accuracy, Agent Goal Accuracy), SQL і класичні BLEU, ROUGE. Ragas уміє автоматично генерувати тестові набори питань з ваших документів і працює з LangChain та інструментами моніторингу. Ліцензія Apache 2.0.', 'Ragas is one of the best-known RAG evaluation tools. Context Precision and Context Recall show whether retrieval found the right chunks, Faithfulness whether the answer sticks to them without inventing, and Response Relevancy whether it addresses the question; there is also Noise Sensitivity, agent and tool-call metrics (Tool Call Accuracy, Agent Goal Accuracy), SQL and classic BLEU and ROUGE. Ragas can generate test question sets from your documents automatically and works with LangChain and observability tools. Apache 2.0 license.', 'Метрики пошуку: Context Precision, Recall
Faithfulness і Response Relevancy
Метрики агентів і інструментів
Генерація тестових наборів', 'Retrieval metrics: Context Precision, Recall
Faithfulness and Response Relevancy
Agent and tool-call metrics
Test set generation', 'QA-інженери, розробники й ML-інженери, що перевіряють якість відповідей чат-ботів, RAG-систем і АІ-агентів', 'QA engineers, developers and ML engineers checking the answer quality of chatbots, RAG systems and AI agents', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
