-- garak — Тестування, Безпека коду та застосунків
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/nvidia/garak' OR LOWER(`name`) = 'garak')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'garak', NULL, 'https://github.com/NVIDIA/garak', NULL, NULL, 'Відкритий сканер вразливостей LLM від NVIDIA: перевіряє модель на промпт-ін’єкції, джейлбрейки, витоки й галюцинації.', 'Open-source LLM vulnerability scanner from NVIDIA: probes a model for prompt injection, jailbreaks, leaks and hallucination.', 'garak (Generative AI Red-teaming & Assessment Kit) — це «nmap для LLM»: він надсилає моделі чи застосунку сотні атакувальних запитів і перевіряє, чи вдалося змусити їх поводитися небажано. Набори проб охоплюють джейлбрейки типу DAN, промпт-ін’єкції зокрема через кодування, витік навчальних даних, токсичний контент, дезінформацію, галюцинації (зокрема вигадані назви пакетів) і XSS. Підтримує Hugging Face, OpenAI, AWS Bedrock, NVIDIA NIM, LiteLLM, llama.cpp і будь-які REST-ендпоінти. Видає звіт із відсотком невдалих перевірок. Ліцензія Apache 2.0.', 'garak (Generative AI Red-teaming & Assessment Kit) is an "nmap for LLMs": it sends hundreds of attack prompts to a model or app and checks whether it can be made to misbehave. Probe sets cover DAN-style jailbreaks, prompt injection including encoding tricks, training data replay, toxic content, misinformation, hallucination (including made-up package names) and XSS. Supports Hugging Face, OpenAI, AWS Bedrock, NVIDIA NIM, LiteLLM, llama.cpp and any REST endpoint. Produces a report with failure rates per probe. Apache 2.0 license.', 'Проби джейлбрейків і промпт-ін’єкцій
Витоки, токсичність, галюцинації
Будь-яка модель чи REST API
Звіт із відсотком невдач', 'Jailbreak and prompt injection probes
Leaks, toxicity, hallucination
Any model or REST API
Report with failure rates', 'Тестувальники, пентестери й команди безпеки, що шукають промпт-ін’єкції, джейлбрейки й витоки в LLM-застосунках', 'Testers, pentesters and security teams looking for prompt injections, jailbreaks and leaks in LLM applications', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
