-- PyRIT — Тестування, Безпека коду та застосунків
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/microsoft/pyrit' OR LOWER(`name`) = 'pyrit')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'PyRIT', NULL, 'https://github.com/microsoft/PyRIT', NULL, NULL, 'Відкритий інструмент red teaming для генеративного АІ від Microsoft AI Red Team: автоматичні скани й багатокрокові атаки.', 'Open-source generative AI red teaming toolkit from the Microsoft AI Red Team: automated scans and multi-turn attacks.', 'PyRIT (Python Risk Identification Tool) допомагає знаходити проблеми безпеки й безпечності в генеративних АІ-системах. Є сканер для командного рядка, графічний інтерфейс CoPyRIT для інтерактивного тестування в браузері й Python-фреймворк для власних сценаріїв. Підтримує адаптивні багатокрокові атаки, коли атакувальна модель поступово підводить ціль до небажаної відповіді, і підключається до OpenAI, Anthropic, Azure OpenAI, Ollama, Hugging Face, а також до HTTP, WebSocket і вебінтерфейсів через Playwright. Ліцензія MIT.', 'PyRIT (Python Risk Identification Tool) helps find security and safety issues in generative AI systems. It offers a command-line scanner, the CoPyRIT GUI for interactive testing in the browser and a Python framework for custom workflows. It supports adaptive multi-turn attacks, where an attacker model gradually steers the target toward an unwanted answer, and connects to OpenAI, Anthropic, Azure OpenAI, Ollama and Hugging Face as well as HTTP, WebSocket and web UIs via Playwright. MIT license.', 'Автоматичний сканер і GUI CoPyRIT
Багатокрокові адаптивні атаки
Моделі, API й вебінтерфейси як цілі
Python-фреймворк для сценаріїв', 'Automated scanner and CoPyRIT GUI
