-- Giskard — Тестування, Моніторинг і оцінка LLM, Безпека коду та застосунків
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/giskard-ai/giskard' OR LOWER(`name`) = 'giskard')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Giskard', NULL, 'https://github.com/Giskard-AI/giskard', NULL, NULL, 'Відкрита бібліотека для тестування LLM-агентів: перевірки якості з LLM-суддею і сканер вразливостей за OWASP LLM Top 10.', 'Open-source library for testing LLM agents: quality checks with LLM-as-judge and an OWASP LLM Top 10 vulnerability scanner.', 'Giskard v3 складається з двох пакетів. giskard-checks дає сценарії й готові перевірки, зокрема оцінки з LLM-суддею на обґрунтованість відповіді та відповідність правилам. giskard-scan генерує атакувальні тести з опису агента звичайною мовою — промпт-ін’єкції, джейлбрейки, шкідливий контент, стереотипи, дезінформацію — за категоріями OWASP LLM Top 10, а quality_scan перевіряє якість відповідей за базою знань. Версія 3 зосереджена на багатокрокових діалогах; потрібен Python 3.12+. Ліцензія Apache 2.0.', 'Giskard v3 consists of two packages. giskard-checks provides scenarios and built-in checks, including LLM-as-judge assessments of groundedness and conformity. giskard-scan generates adversarial tests from a plain-language agent description, covering prompt injection, jailbreaks, harmful content, stereotypes and misinformation, aligned with OWASP LLM Top 10 categories, and quality_scan evaluates answers against a knowledge base. Version 3 focuses on multi-turn conversations and needs Python 3.12+. Apache 2.0 license.', 'Перевірки з LLM-суддею
Сканер за OWASP LLM Top 10
Тести з опису агента
Багатокрокові діалоги', 'LLM-as-judge checks
OWASP LLM Top 10 scanner
Tests from an agent description
Multi-turn conversations', 'QA-інженери, розробники й ML-інженери, що перевіряють якість відповідей чат-ботів, RAG-систем і АІ-агентів', 'QA engineers, developers and ML engineers checking the answer quality of chatbots, RAG systems and AI agents', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
