SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'inspect.aisi.org.uk' OR LOWER(`name`) = 'inspect ai')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Inspect AI', NULL, 'https://inspect.aisi.org.uk', NULL, NULL, 'Відкритий фреймворк для оцінювання LLM і агентів від британського AI Security Institute: понад 200 готових бенчмарків.', 'Open-source framework for LLM and agent evaluations from the UK AI Security Institute: 200+ ready benchmarks.', 'Inspect створили UK AI Security Institute і Meridian Labs. Оцінювання збирається з наборів даних, «розв’язувачів» (від одного запиту до агента з інструментами) і оцінювачів (порівняння тексту, оцінка іншою моделлю або власна схема). Є вбудовані інструменти bash, Python, редагування тексту, вебпошуку й керування комп’ютером, підтримка MCP і зовнішніх агентів, ізоляція коду моделі в Docker чи Kubernetes, розширення для VS Code і вебпереглядач журналів. Бібліотека Inspect Evals містить понад 200 готових бенчмарків, працює з 20+ провайдерами моделей. Ліцензія MIT.', 'Inspect was built by the UK AI Security Institute and Meridian Labs. An evaluation combines datasets, solvers (from a single generate call to a tool-using agent) and scorers (text matching, model grading or custom schemes). It has built-in bash, Python, text editing, web search and computer tools, MCP and external agent support, sandboxing of model code in Docker or Kubernetes, a VS Code extension and a web log viewer. The Inspect Evals library holds 200+ ready benchmarks, and it works with 20+ model providers. MIT license.', 'Розв’язувачі, оцінювачі, агенти
Ізоляція в Docker і Kubernetes
Inspect Evals: 200+ бенчмарків
Розширення VS Code і переглядач журналів', 'Solvers, scorers and agents
Docker and Kubernetes sandboxing
Inspect Evals: 200+ benchmarks
VS Code extension and log viewer', 'QA-інженери, розробники й ML-інженери, що перевіряють якість відповідей чат-ботів, RAG-систем і АІ-агентів', 'QA engineers, developers and ML engineers checking the answer quality of chatbots, RAG systems and AI agents', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
