SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/eleutherai/lm-evaluation-harness' OR LOWER(`name`) = 'lm evaluation harness')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'LM Evaluation Harness', NULL, 'https://github.com/EleutherAI/lm-evaluation-harness', NULL, NULL, 'Відкритий фреймворк EleutherAI для перевірки мовних моделей на академічних бенчмарках; основа Open LLM Leaderboard.', 'EleutherAI open-source framework for testing language models on academic benchmarks; the backend of the Open LLM Leaderboard.', 'lm-evaluation-harness запускає понад 60 стандартних академічних бенчмарків із сотнями підзадач через один інтерфейс. Працює з моделями Hugging Face Transformers (зокрема квантизованими), vLLM і SGLang для швидкого інференсу, llama.cpp, OpenVINO, а також з API, сумісними з OpenAI, і Anthropic. Саме на ньому працював Open LLM Leaderboard від Hugging Face. Корисний, коли треба порівняти моделі перед вибором або перевірити, що донавчання чи квантизація не погіршили якість. Ліцензія MIT.', 'lm-evaluation-harness runs 60+ standard academic benchmarks with hundreds of subtasks through one interface. It works with Hugging Face Transformers models (including quantized ones), vLLM and SGLang for fast inference, llama.cpp and OpenVINO, as well as OpenAI-compatible APIs and Anthropic. It powered the Hugging Face Open LLM Leaderboard. Useful for comparing models before choosing one or checking that fine-tuning or quantization did not hurt quality. MIT license.', '60+ бенчмарків, сотні підзадач
Transformers, vLLM, SGLang, llama.cpp
API, сумісні з OpenAI
Основа Open LLM Leaderboard', '60+ benchmarks, hundreds of subtasks
