SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'langwatch.ai' OR LOWER(`name`) = 'langwatch')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'LangWatch', NULL, 'https://langwatch.ai', NULL, NULL, 'Відкрита платформа для моніторингу й оцінювання АІ-агентів: трасування, оцінювання, симуляційні тести агентів, керування промптами.', 'Open-source platform for observing and evaluating AI agents: tracing, evaluations, agent simulation tests and prompt management.', 'LangWatch трасує виклики LLM і агентів у продакшені, запускає оцінювання й дозволяє створювати симуляційні тести, де агент (зокрема голосовий) проходить сценарії діалогу з імітованим користувачем. Є керування промптами, АІ-шлюз з одним ендпоінтом, сумісним з OpenAI та Anthropic, з бюджетами й маршрутизацією, а також облік використання асистентів коду на кшталт Claude Code і Copilot. Ядро під ліцензією Apache 2.0, SDK — MIT, можна розгорнути у себе; є хмарна версія LangWatch Cloud.', 'LangWatch traces LLM and agent calls in production, runs evaluations and lets you build simulation tests where an agent (including a voice agent) goes through conversation scenarios with a simulated user. It has prompt management, an AI gateway with one OpenAI- and Anthropic-compatible endpoint, budgets and routing, plus usage tracking for coding assistants such as Claude Code and Copilot. Core under Apache 2.0, SDKs under MIT, self-hostable; LangWatch Cloud is also available.', 'Симуляційні тести агентів
Трасування й оцінювання
Керування промптами
Self-hosting або хмара', 'Agent simulation tests
Tracing and evaluations
