-- NeMo Guardrails — Безпека коду та застосунків, Фреймворки для LLM-застосунків
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'github.com/nvidia/nemo-guardrails' OR LOWER(`name`) = 'nemo guardrails')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'NeMo Guardrails', NULL, 'https://github.com/NVIDIA/NeMo-Guardrails', NULL, NULL, 'Відкритий набір інструментів NVIDIA для програмованих «запобіжників» LLM-застосунків: фільтри входу, виходу, діалогу й інструментів.', 'NVIDIA open-source toolkit for programmable LLM app guardrails: input, output, dialog and tool rails.', 'NeMo Guardrails стоїть між застосунком і моделлю. Вхідні запобіжники перевіряють і змінюють повідомлення користувача, діалогові — керують сценарієм розмови, пошукові — фільтрують фрагменти в RAG, запобіжники виконання — контролюють виклики інструментів, вихідні — перевіряють відповідь перед показом. Сценарії описуються мовою Colang. Є вбудоване виявлення джейлбрейків і промпт-ін’єкцій, самоперевірка фактів і виявлення галюцинацій, інтеграція з LangChain. Для тестувальника — і інструмент, і об’єкт перевірки: чи справді запобіжники спрацьовують. Ліцензія Apache 2.0.', 'NeMo Guardrails sits between the app and the model. Input rails check and modify user messages, dialog rails steer the conversation flow, retrieval rails filter RAG chunks, execution rails control tool calls and output rails vet the answer before it is shown. Flows are written in the Colang language. It has built-in jailbreak and prompt injection detection, fact self-checking and hallucination detection, and LangChain integration. For testers it is both a tool and something to verify: do the rails actually fire. Apache 2.0 license.', 'Запобіжники входу, виходу, діалогу, RAG
Контроль викликів інструментів
Виявлення джейлбрейків
Мова сценаріїв Colang', 'Input, output, dialog and RAG rails
Tool call control
Jailbreak detection
Colang flow language', 'Розробники LLM-застосунків, яким потрібні перевірки вхідних і вихідних даних моделі в продакшені', 'LLM application developers who need input and output checks around the model in production', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
