-- Guardrails AI — Безпека коду та застосунків, Фреймворки для LLM-застосунків
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'guardrailsai.com' OR LOWER(`name`) = 'guardrails ai')), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Guardrails AI', NULL, 'https://www.guardrailsai.com', NULL, NULL, 'Відкритий Python-фреймворк для перевірок вхідних і вихідних даних LLM та отримання структурованих відповідей; каталог валідаторів Guardrails Hub.', 'Open-source Python framework for LLM input and output checks and structured output; Guardrails Hub validator catalog.', 'Guardrails AI будує «guard» із валідаторів, які перевіряють запит і відповідь моделі на конкретні ризики, і допомагає отримати від LLM дані за схемою Pydantic — через виклик функцій або інструкції в промпті. Готові валідатори встановлюються з каталогу Guardrails Hub. Можна запустити як сервіс з REST API командою guardrails start. Ліцензія Apache 2.0. Розробники оголосили припинення хостингового віддаленого інференсу валідаторів із 25 серпня 2026 року; валідатори переходять в окремі pip-пакети.', 'Guardrails AI builds a guard out of validators that check the model request and response for specific risks, and helps get data from an LLM matching a Pydantic schema, via function calling or prompt instructions. Ready validators install from the Guardrails Hub catalog. It can run as a REST API service with guardrails start. Apache 2.0 license. The maintainers announced the end of hosted remote validator inference from August 25, 2026; validators are moving to standalone pip packages.', 'Валідатори входу й виходу
Структуровані відповіді за Pydantic
Каталог Guardrails Hub
Режим сервера з REST API', 'Input and output validators
Structured output via Pydantic
Guardrails Hub catalog
Server mode with REST API', 'Розробники LLM-застосунків, яким потрібні перевірки вхідних і вихідних даних моделі в продакшені', 'LLM application developers who need input and output checks around the model in production', 'desktop', 'none', 'published', 0, 'found', @uid, '2026-11-05 00:00:00' FROM DUAL WHERE @new = 1;
